INSERT INTO public.mi_report_user_defined (id, report_name, description, query_definition, created_by, last_updated_on, active) VALUES(nextval('mi_report_user_defined_seq'), 'Survey EMP Operators V1', 'Feedback responses submitted by Operators after completing and submitting an EMP application for regulatory review.', 'SELECT rf.request_id AS "Workflow ID", ''EMP Issuance'' AS "Workflow Type", acc.name AS "Account", rf.submitter_id AS "User$userfullname", rf.submitter_id AS "Email$useremail", CASE au.code WHEN ''operator_admin'' THEN ''Operator admin'' WHEN ''operator'' THEN ''Operator'' WHEN ''consultant_agent'' THEN ''Consultant agent'' ELSE au.code END as "User type", (rf.payload ->> ''version'')::int AS "Version", CASE rf.payload ->> ''reportCompletionEaseRating'' WHEN ''VERY_EASY'' THEN ''Very easy'' WHEN ''EASY'' THEN ''Easy'' WHEN ''NEITHER_EASY_NOR_DIFFICULT'' THEN ''Neither easy or difficult'' WHEN ''DIFFICULT'' THEN ''Difficult'' WHEN ''VERY_DIFFICULT'' THEN ''Very difficult'' END AS "Report completion ease rating", (SELECT string_agg( CASE m.val WHEN ''TYPED_INTO_FORM_SECTIONS'' THEN ''Typed answers into the form sections'' WHEN ''UPLOADED_SINGLE_SHIP_EU_XML_FILE'' THEN ''Uploaded an EU XML for a single ship'' WHEN ''UPLOADED_XML_FILE'' THEN ''Uploaded an XML file to add ships'' WHEN ''IMPORTED_FROM_DATA_SUPPLIER'' THEN ''Imported data from an appointed data supplier'' WHEN ''OTHER'' THEN ''Other'' ELSE m.val END, '', '' ORDER BY m.ord) FROM jsonb_array_elements_text(rf.payload -> ''reportCompletionMethods'') WITH ORDINALITY AS m(val, ord)) AS "Report completion methods", rf.payload ->> ''otherReportCompletionMethods'' AS "Other report completion methods", (SELECT string_agg( CASE g.val WHEN ''OPERATOR_DETAILS'' THEN ''Operator details'' WHEN ''SHIPS_CALCULATION_EMISSIONS'' THEN ''List of ships and calculation of maritime emissions'' WHEN ''EMISSION_SOURCES'' THEN ''Procedures related to emission sources and emissions factors'' WHEN ''MONITORING_APPROACH'' THEN ''Procedures related to the monitoring of greenhouse gas emissions and fuel consumption'' WHEN ''DATA_GAPS'' THEN ''Data gaps'' WHEN ''MANDATE'' THEN ''Delegated responsibility'' WHEN ''MANAGEMENT_PROCEDURES'' THEN ''Management procedures'' WHEN ''CONTROL_ACTIVITIES'' THEN ''Control activities'' WHEN ''ABBREVIATIONS_AND_DEFINITIONS'' THEN ''List of definitions and abbreviations'' WHEN ''ADDITIONAL_DOCUMENTS'' THEN ''Additional information'' WHEN ''NO_FEEDBACK'' THEN ''No, I do not want to give feedback on any of these sections'' ELSE g.val END, '', '' ORDER BY g.ord) FROM jsonb_array_elements_text(rf.payload -> ''feedbackReviewGroups'') WITH ORDINALITY AS g(val, ord)) AS "Feedback review groups", rf.payload ->> ''feedbackReviewGroupsComment'' AS "Feedback review groups comment", rf.payload ->> ''additionalComments'' AS "Additional comments" FROM request_feedback rf JOIN request_account ra on ra.id = rf.request_id JOIN account acc on ra.account_id = acc.id::VARCHAR LEFT JOIN au_authority au on au.user_id = rf.submitter_id AND acc.id = au.account_id WHERE rf.type = ''EMP_ISSUANCE_SUBMIT'' AND (rf.payload ->> ''version'')::int = 1 AND rf.status = ''SUBMITTED'';', 'SYSTEM', now(), true);
