S_CALCULATION_EMISSIONS'' THEN ''List of ships and calculation of maritime emissions'' WHEN ''EMISSION_SOURCES'' THEN ''Procedures related to emission sources and emissions factors'' WHEN ''MONITORING_APPROACH'' THEN ''Procedures related to the monitoring of greenhouse gas emissions and fuel consumption'' WHEN ''DATA_GAPS'' THEN ''Data gaps'' WHEN ''MANDATE'' THEN ''Delegated responsibility'' WHEN ''MANAGEMENT_PROCEDURES'' THEN ''Management procedures'' WHEN ''CONTROL_ACTIVITIES'' THEN ''Control activities'' WHEN ''ABBREVIATIONS_AND_DEFINITIONS'' THEN ''List of definitions and abbreviations'' WHEN ''ADDITIONAL_DOCUMENTS'' THEN ''Additional information'' WHEN ''NO_FEEDBACK'' THEN ''No, I do not want to give feedback on any of these sections'' ELSE g.val END, '', '' ORDER BY g.ord) FROM jsonb_array_elements_text(rf.payload -> ''feedbackReviewGroups'') WITH ORDINALITY AS g(val, ord)) AS "Feedback review groups", rf.payload ->> ''feedbackReviewGroupsComment'' AS "Feedback review groups comment", rf.payload ->> ''additionalComments'' AS "Additional comments" FROM request_feedback rf JOIN request_account ra on ra.id = rf.request_id JOIN account acc on ra.account_id = acc.id::VARCHAR LEFT JOIN au_authority au on au.user_id = rf.submitter_id AND acc.id = au.account_id WHERE rf.type = ''EMP_ISSUANCE_SUBMIT'' AND (rf.payload ->> ''version'')::int = 1 AND rf.status = ''SUBMITTED'';');

