s'' WHEN ''UNCORRECTED_NON_COMPLIANCES'' THEN ''Uncorrected non-compliances'' WHEN ''RECOMMENDED_IMPROVEMENTS'' THEN ''Recommended improvements'' WHEN ''EMISSIONS_REDUCTION_CLAIM_VERIFICATION'' THEN ''Verify the emissions reduction claim'' WHEN ''CLOSE_DATA_GAPS_METHODOLOGIES'' THEN ''Methodologies to close data gaps'' WHEN ''MATERIALITY_LEVEL'' THEN ''Further information of relevance to the opinion'' WHEN ''NO_FEEDBACK'' THEN ''No, I do not want to give feedback on any of these sections'' ELSE g.val END, '', '' ORDER BY g.ord) FROM jsonb_array_elements_text(rf.payload -> ''feedbackReviewGroups'') WITH ORDINALITY AS g(val, ord)) AS "Feedback review groups", rf.payload ->> ''feedbackReviewGroupsComment'' AS "Feedback review groups comment", rf.payload ->> ''additionalComments'' AS "Additional comments" FROM request_feedback rf JOIN request_account ra on ra.id = rf.request_id JOIN account acc on ra.account_id = acc.id::VARCHAR LEFT JOIN au_authority au on au.user_id = rf.submitter_id WHERE rf.type = ''AER_VERIFICATION_SUBMIT'' AND (rf.payload ->> ''version'')::int = 1 AND rf.status = ''SUBMITTED'';', 'SYSTEM', now(), true);
INSERT INTO public.mi_report_user_defined_category_mapping (mi_report_id, category_id) VALUES((SELECT id FROM public.mi_report_user_defined WHERE report_name = 'Survey AER Verifier V1'), (SELECT id FROM public.mi_report_user_defined_category WHERE name = 'Management'));
INSERT INTO public.mi_report_user_defined_history (id, mi_report_id, change_type, submitted_by, submission_date, reason_for_change, report_name, categories, description, query_definition) VALUES (nextval('mi_report_user_defined_history_seq'), (SELECT id FROM public.mi_report_user_defined WHERE report_name = 'Survey AER Verifier V1'), 'CREATE', 'SYSTEM', now(), null, 'Survey AER Verifier V1', 'Management', 'Feedback responses submitted by Verifiers after submitting a Verification Report and Verification Opinion Statement to the Operator.', 'SELECT rf.request_id AS "Workflow ID", ''AER Verification'' AS "Workflow Type", acc.name AS "Account", rf.submitter_id AS "User$userfullname", rf.submitter_id AS "Email$useremail", CASE au.code WHEN ''verifier_admin'' THEN ''Verifier admin'' WHEN ''verifier'' THEN ''Verifier'' ELSE au.code END as "User type", (rf.payload ->> ''version'')::int AS "Version", CASE rf.payload ->> ''opinionStatementEaseRating'' WHEN ''VERY_EASY'' THEN ''Very easy'' WHEN ''EASY'' THEN ''Easy'' WHEN ''NEITHER_EASY_NOR_DIFFICULT'' THEN ''Neither easy or difficult'' WHEN ''DIFFICULT'' THEN ''Difficult'' WHEN ''VERY_DIFFICULT'' THEN ''Very difficult'' END AS "Report review ease rating", (SELECT string_agg( CASE m.val WHEN ''TYPED_INTO_FORM_SECTIONS'' THEN ''Typed answers into the form sections'' WHEN ''IMPORTED_FROM_DATA_SUPPLIER'' THEN ''Imported data from an appointed data supplier'' WHEN ''OTHER'' THEN ''Other'' ELSE m.val END, '', '' ORDER BY m.ord) FROM jsonb_array_elements_text(rf.payload -> ''reportCompletionMethods'') WITH ORDINALITY AS m(val, ord)) AS "Report completion methods", rf.payload ->> ''otherReportCompletionMethods'' AS "Other report completion methods", (SELECT string_agg( CASE g.val WHEN ''VERIFIER_DETAILS'' THEN ''Verifier details'' WHEN ''OPINION_STATEMENT'' THEN ''Opinion statement'' WHEN ''ETS_COMPLIANCE_RULES'' THEN ''Compliance with ETS rules'' WHEN ''COMPLIANCE_MONITORING_REPORTING'' THEN ''Compliance with monitoring and reporting principles'' WHEN ''OVERALL_DECISION'' THEN ''Overall decision'' WHEN ''UNCORRECTED_MISSTATEMENTS'' THEN ''Uncorrected misstatements'' WHEN ''UNCORRECTED_NON_CONFORMITIES'' THEN ''Uncorrected non-conformities'' WHEN ''UNCORRECTED_NON_COMPLIANCES'' THEN ''Uncorrected non-compliances'' WHEN ''RECOMMENDED_IMPROVEMENTS'' THEN ''Recommended improvements'' WHEN ''EMISSIONS_REDUCTION_CLAIM_VERIFICATION'' THEN ''Verify the emissions reduction claim'' WHEN ''CLOSE_DATA_GAPS_METHODOLOGIES'' THEN ''Methodologies to close data gaps'' WHEN ''MATERIALITY_LEVEL'' THEN ''Further information of relevance to the opinion'' WHEN ''NO_FEEDBACK'' THEN ''No, I do not want to give feedback on any of these sections'' ELSE g.val END, '', '' ORDER BY g.ord) FROM jsonb_array_elements_text(rf.payload -> ''feedbackReviewGroups'') WITH ORDINALITY AS g(val, ord)) AS "Feedback review groups", rf.payload ->> ''feedbackReviewGroupsComment'' AS "Feedback review groups comment", rf.payload ->> ''additionalComments'' AS "Additional comments" FROM request_feedback rf JOIN request_account ra on ra.id = rf.request_id JOIN account acc on ra.account_id = acc.id::VARCHAR LEFT JOIN au_authority au on au.user_id = rf.submitter_id WHERE rf.type = ''AER_VERIFICATION_SUBMIT'' AND (rf.payload ->> ''version'')::int = 1 AND rf.status = ''SUBMITTED'';');

